/**
 * Flags Open invoices whose Due_Date__c is in the past as Overdue and writes
 * exactly one FB_Job_Summary__c run record in finish().
 *
 * Implements Database.Stateful so the running totals survive across every
 * chunk of the job, regardless of the batch size. Without Stateful, each
 * chunk (and finish) executes on a fresh instance and the totals reset to 0.
 *
 * Bulk-safe: uses Database.update(records, false) so a single record failing
 * (for example the active validation rule that rejects Overdue invoices with a
 * blank Customer_Email__c) does not abort the rest of the chunk.
 */
public with sharing class OverdueInvoiceBatch implements Database.Batchable<SObject>, Database.Stateful {

    // Running totals, accumulated across every chunk of the job.
    private Integer recordsUpdated = 0;
    private Integer recordsFailed = 0;
    private Decimal overdueAmount = 0;

    /**
     * No-argument constructor (required for Database.executeBatch and for the
     * tests that instantiate the class directly).
     */
    public OverdueInvoiceBatch() {
        // nothing to initialise here
    }

    /**
     * Query every Open invoice whose due date has already passed.
     */
    public Database.QueryLocator start(Database.BatchableContext bc) {
        return Database.getQueryLocator([
            SELECT Id, Name, Status__c, Due_Date__c, Amount__c, Customer_Email__c
            FROM FB_Invoice__c
            WHERE Status__c = 'Open'
              AND Due_Date__c < :Date.today()
        ]);
    }

    /**
     * Mark each invoice in the chunk as Overdue, tolerating per-record failures.
     */
    public void execute(Database.BatchableContext bc, List<FB_Invoice__c> scope) {
        if (scope == null || scope.isEmpty()) {
            return;
        }

        for (FB_Invoice__c inv : scope) {
            if (inv != null) {
                inv.Status__c = 'Overdue';
            }
        }

        // allOrNone = false -> partial success, failures reported per record.
        List<Database.SaveResult> results = Database.update(scope, false);

        for (Integer i = 0; i < results.size(); i++) {
            if (results[i].isSuccess()) {
                recordsUpdated++;
                Decimal amt = scope[i].Amount__c;
                // Blank amount counts as 0.
                overdueAmount += (amt == null ? 0 : amt);
            } else {
                recordsFailed++;
            }
        }
    }

    /**
     * Insert exactly one run summary for the job.
     */
    public void finish(Database.BatchableContext bc) {
        FB_Job_Summary__c summary = new FB_Job_Summary__c(
            Job_Name__c = 'OverdueInvoiceBatch',
            Records_Updated__c = recordsUpdated,
            Records_Failed__c = recordsFailed,
            Overdue_Amount__c = overdueAmount
        );
        insert summary;
    }
}
