/**
 * Handler for ContactTrigger.
 *
 * Bulk-safety notes:
 *  - Accounts are queried at most once per trigger execution. The before context
 *    builds/refreshes the cache; the after-insert context reuses it, so a 200-row
 *    insert costs exactly 1 SOQL query.
 *  - The cache is refreshed on every before context so that consecutive DML
 *    operations in the same transaction (e.g. insert then update in a test) do
 *    not read stale Account data.
 *  - Account phone updates are collected into a single Map and written with one
 *    DML statement.
 *
 * Worst case per DML operation: 1 SOQL query + 1 DML statement.
 *
 * Declared `without sharing` to preserve the original trigger's system-mode behaviour.
 */
public without sharing class ContactTriggerHandler {

    private static Map<Id, Account> accountCache;

    public static void beforeInsert(List<Contact> newContacts) {
        Map<Id, Account> accounts = getAccounts(newContacts, true);
        for (Contact c : newContacts) {
            if (c.AccountId == null) {
                continue;
            }
            Account a = accounts.get(c.AccountId);
            if (a == null) {
                continue;
            }
            if (String.isBlank(c.MailingCountry)) {
                c.MailingCountry = a.BillingCountry;
            }
            if (String.isBlank(c.LeadSource)) {
                c.LeadSource = a.AccountSource;
            }
        }
    }

    public static void beforeUpdate(List<Contact> newContacts) {
        Map<Id, Account> accounts = getAccounts(newContacts, true);
        for (Contact c : newContacts) {
            if (c.AccountId == null) {
                continue;
            }
            Account a = accounts.get(c.AccountId);
            if (a == null) {
                continue;
            }
            if (String.isBlank(c.MailingCountry)) {
                c.MailingCountry = a.BillingCountry;
            }
            // LeadSource is only defaulted on insert, exactly as before.
        }
    }

    public static void afterInsert(List<Contact> newContacts) {
        // The before-insert context already populated the cache in this same
        // trigger execution, so no extra SOQL is required here.
        Map<Id, Account> accounts = getAccounts(newContacts, false);

        Map<Id, Account> accountsToUpdate = new Map<Id, Account>();
        for (Contact c : newContacts) {
            if (c.AccountId == null || String.isBlank(c.Phone)) {
                continue;
            }
            // The first contact (in trigger order) for a given account wins.
            if (accountsToUpdate.containsKey(c.AccountId)) {
                continue;
            }
            Account a = accounts.get(c.AccountId);
            if (a == null || String.isNotBlank(a.Phone)) {
                continue;
            }
            accountsToUpdate.put(c.AccountId, new Account(Id = c.AccountId, Phone = c.Phone));
        }

        if (!accountsToUpdate.isEmpty()) {
            update accountsToUpdate.values();
        }
    }

    /**
     * Returns the Account records for every AccountId referenced by the supplied
     * contacts. When `refresh` is true (the before contexts) the cache is rebuilt
     * so consecutive DML operations see current data; otherwise the existing cache
     * is reused.
     */
    private static Map<Id, Account> getAccounts(List<Contact> contacts, Boolean refresh) {
        if (refresh || accountCache == null) {
            Set<Id> accountIds = new Set<Id>();
            for (Contact c : contacts) {
                if (c.AccountId != null) {
                    accountIds.add(c.AccountId);
                }
            }
            accountCache = new Map<Id, Account>();
            if (!accountIds.isEmpty()) {
                accountCache = new Map<Id, Account>([
                    SELECT Id, BillingCountry, AccountSource, Phone
                    FROM Account
                    WHERE Id IN :accountIds
                ]);
            }
        }
        return accountCache;
    }
}
