    /** Asserts the full documented field set of a handover task. */
    private static void assertHandoverTask(Task t, Opportunity opp, Id expectedOwner) {
        System.assertEquals(KICKOFF, t.Subject, 'Task subject should be the kick-off subject');
        System.assertEquals(opp.Id, t.WhatId, 'Task should be related to the opportunity');
        System.assertEquals(expectedOwner, t.OwnerId, 'Task owner should be the opportunity owner');
        System.assertEquals(opp.CloseDate.addDays(7), t.ActivityDate,
