```java
/**
 * Domain class for the Opportunity SObject.
 *
 * Implements the following validation rules:
 *  1. On insert and on update, Amount must not be negative.
 *  2. On update, an opportunity whose StageName was already 'Closed Won'
 *     before the update cannot have its Amount changed.
 *
 * Errors are added to the offending record only (on the Amount field) via the
 * fflib_SObjectDomain.error(message, record, field) helper so that they are
 * also captured in fflib_SObjectDomain.Errors for unit tests.
 */
public with sharing class Opportunities extends fflib_SObjectDomain
{
    /**
     * Standard fflib domain constructor.
     */
    public Opportunities(List<SObject> sObjectList)
    {
        super(sObjectList);
    }

    /**
     * Standard fflib constructor used by fflib_SObjectDomain.triggerHandler
     * to instantiate the domain class reflectively.
     */
    public class Constructor implements fflib_SObjectDomain.IConstructable
    {
        public fflib_SObjectDomain construct(List<SObject> sObjectList)
        {
            return new Opportunities(sObjectList);
        }
    }

    /**
     * Validation hook invoked by fflib on before insert and before update.
     *
     * Rule 1: Amount must not be negative.
     */
    public override void onValidate()
    {
        for (Opportunity opp : (List<Opportunity>) Records)
        {
            if (opp.Amount != null && opp.Amount < 0)
            {
                error('Amount cannot be negative.', opp, Opportunity.Amount);
            }
        }
    }

    /**
     * Before update hook invoked by fflib. The framework passes the map of
     * existing (pre-update) records keyed by Id, so no SOQL is required.
     *
     * Rule 2: an opportunity whose StageName was already 'Closed Won' before
     * the update cannot have its Amount changed. Because we look at the old
     * value of StageName, closing an opportunity as won and changing the
     * Amount in the same update is allowed.
     */
    public override void onBeforeUpdate(Map<Id, SObject> existingRecords)
    {
        for (Opportunity opp : (List<Opportunity>) Records)
        {
            Opportunity oldOpp = (Opportunity) existingRecords.get(opp.Id);
            if (oldOpp == null)
            {
                continue;
            }

            if (oldOpp.StageName == 'Closed Won' && oldOpp.Amount != opp.Amount)
            {
                error('Amount cannot change on a won opportunity.', opp, Opportunity.Amount);
            }
        }
    }
}
