        return (List<Opportunity>) selectSObjectsById(opportunityIds);
    }

    /**
     * Returns the open opportunities (IsClosed = false) for the supplied accounts,
     * ordered by Amount descending (nulls last), then CloseDate ascending.
     * Returns at most maxRecords rows, using a single query built from the
     * selector's query factory so its field list and security settings apply.
     */
    public List<Opportunity> selectTopOpenByAccountIds(Set<Id> accountIds, Integer maxRecords) {
        if (accountIds == null || accountIds.isEmpty() || maxRecords == null || maxRecords <= 0) {
            return new List<Opportunity>();
        }

        fflib_QueryFactory queryFactory = newQueryFactory();
        queryFactory.selectField('Account.Name');
        queryFactory.setCondition('AccountId IN :accountIds AND IsClosed = false');
        queryFactory.addOrdering('Amount DESC NULLS LAST');
        queryFactory.addOrdering('CloseDate ASC');
        queryFactory.setLimit(maxRecords);

        return (List<Opportunity>) Database.query(queryFactory.toSOQL());
    }
}
