public with sharing class HouseholdService {
    /**
     * Creates ONE new NPSP Household Account from the supplied (new) Contacts.
     * The first Contact becomes the household's primary contact.
     *
     * @param members new Contacts (no Id, no AccountId) to be placed in a single household
     * @return the Id of the newly created Household Account
     * @throws IllegalArgumentException if members is null or empty
     */
    public static Id createHousehold(List<Contact> members) {
        if (members == null || members.isEmpty()) {
            throw new IllegalArgumentException('members must not be null or empty');
        }

        // Resolve the Household Account record type by DeveloperName (no hard-coded Ids).
        Schema.RecordTypeInfo hhRtInfo = Schema.SObjectType.Account
            .getRecordTypeInfosByDeveloperName()
            .get('HH_Account');
        if (hhRtInfo == null) {
            throw new IllegalArgumentException('Household Account record type (HH_Account) not found.');
        }
        Id hhRecordTypeId = hhRtInfo.getRecordTypeId();

        // Create the household. The Name is only a temporary placeholder required by the
        // platform; NPSP's automatic household naming overwrites it based on the members.
        Account household = new Account(
            RecordTypeId = hhRecordTypeId,
            Name = 'Household'
        );
        insert household;

        // Attach every new contact to this single household.
        for (Contact c : members) {
            c.AccountId = household.Id;
        }
        insert members;

        // Set the first member as the household's primary contact. This update also lets
        // NPSP's household naming trigger recompute the household name/greeting.
        household.npe01__One2OneContact__c = members[0].Id;
        update household;

        return household.Id;
    }
}
