/**
 * GiftService
 *
 * Records gifts that have already been received into an NPSP org running the
 * Household Account model with NPSP Payments enabled.
 *
 * A recorded gift is:
 *   - a Closed Won Opportunity on the donor's household Account,
 *   - with the donor as the Opportunity's Primary Contact holding the Donor
 *     contact role, and every other household member holding the Household
 *     Member contact role (at most one contact role per contact),
 *   - with exactly one paid payment covering the full amount.
 *
 * The class is defensive about NPSP's TDTM automations: those triggers can
 * create contact roles and/or a payment record when the Opportunity is
 * inserted, so after the insert the contact roles and payments are reconciled
 * to the exact required state instead of blindly creating duplicates.
 */
public with sharing class GiftService {

    private static final String STAGE_CLOSED_WON      = 'Closed Won';
    private static final String ROLE_DONOR            = 'Donor';
    private static final String ROLE_HOUSEHOLD_MEMBER = 'Household Member';

    /**
     * Records a gift that has already been received.
     *
     * @param contactId Id of the donor Contact.
     * @param amount    Gift amount. Must be greater than zero.
     * @param giftDate  Date the gift was received.
     * @return          The Id of the Opportunity that was created.
     */
    public static Id recordGift(Id contactId, Decimal amount, Date giftDate) {
        if (amount == null || amount <= 0) {
            throw new IllegalArgumentException('Gift amount must be greater than zero.');
        }
        if (giftDate == null) {
            throw new IllegalArgumentException('Gift date is required.');
        }

        Contact donor = loadDonor(contactId);

        Id householdAccountId = donor.AccountId;
        if (householdAccountId == null) {
            throw new IllegalArgumentException(
                'Contact ' + contactId + ' is not associated with a household Account.'
            );
        }

        Set<Id> householdMemberIds = loadHouseholdMemberIds(householdAccountId);

        Opportunity gift = new Opportunity(
            AccountId                = householdAccountId,
            Name                     = buildGiftName(donor, giftDate),
            StageName                = STAGE_CLOSED_WON,
            CloseDate                = giftDate,
            Amount                   = amount,
            npsp__Primary_Contact__c = donor.Id
        );
        insert gift;

        applyContactRoles(gift.Id, donor.Id, householdMemberIds);
        applyPayment(gift.Id, amount, giftDate);

        return gift.Id;
    }

    /**
     * Loads the donor Contact and validates that it exists.
     */
    private static Contact loadDonor(Id contactId) {
        if (contactId == null) {
            throw new IllegalArgumentException('A Contact Id is required.');
        }

        List<Contact> donors = [
            SELECT Id, FirstName, LastName, AccountId
            FROM Contact
            WHERE Id = :contactId
            LIMIT 1
        ];

        if (donors.isEmpty()) {
            throw new IllegalArgumentException('Contact ' + contactId + ' does not exist.');
        }
        return donors[0];
    }

    /**
     * Returns the Ids of every Contact on the household Account (the donor included).
     */
    private static Set<Id> loadHouseholdMemberIds(Id householdAccountId) {
        Set<Id> memberIds = new Set<Id>();
        for (Contact member : [
            SELECT Id
            FROM Contact
            WHERE AccountId = :householdAccountId
        ]) {
            memberIds.add(member.Id);
        }
        return memberIds;
    }

    /**
     * Builds "<FirstName> <LastName> Donation <yyyy-MM-dd>".
     */
    private static String buildGiftName(Contact donor, Date giftDate) {
        String firstName = donor.FirstName == null ? '' : donor.FirstName;
        String lastName  = donor.LastName  == null ? '' : donor.LastName;
        String donorName = (firstName + ' ' + lastName).trim();
        return donorName + ' Donation ' + String.valueOf(giftDate);
    }

    /**
     * Makes the Opportunity's contact roles match the NPSP credit exactly:
     * the donor holds Donor (and is the primary role), every other household
     * member holds Household Member, and no contact holds more than one role.
     *
     * Existing roles (possibly created by NPSP's TDTM triggers on Opportunity
     * insert) are reconciled rather than duplicated.
     */
    private static void applyContactRoles(Id opportunityId, Id donorId, Set<Id> householdMemberIds) {
        Map<Id, String> desiredRoleByContactId = new Map<Id, String>();
        desiredRoleByContactId.put(donorId, ROLE_DONOR);
        for (Id memberId : householdMemberIds) {
            if (memberId != donorId) {
                desiredRoleByContactId.put(memberId, ROLE_HOUSEHOLD_MEMBER);
            }
        }

        List<OpportunityContactRole> existingRoles = [
            SELECT Id, ContactId, Role, IsPrimary
            FROM OpportunityContactRole
            WHERE OpportunityId = :opportunityId
        ];

        List<OpportunityContactRole> toDelete = new List<OpportunityContactRole>();
        List<OpportunityContactRole> toUpdate = new List<OpportunityContactRole>();
        List<OpportunityContactRole> toInsert = new List<OpportunityContactRole>();
        Set<Id> creditedContactIds = new Set<Id>();

        for (OpportunityContactRole role : existingRoles) {
            String desiredRole = desiredRoleByContactId.get(role.ContactId);

            // Roles for contacts that are not part of this household, or a
            // second role for a contact we already handled, must go.
            if (desiredRole == null || creditedContactIds.contains(role.ContactId)) {
                toDelete.add(role);
                continue;
            }

            creditedContactIds.add(role.ContactId);

            Boolean shouldBePrimary = (role.ContactId == donorId);
            if (role.Role != desiredRole || role.IsPrimary != shouldBePrimary) {
                role.Role      = desiredRole;
                role.IsPrimary = shouldBePrimary;
                toUpdate.add(role);
            }
        }

        for (Id contactId : desiredRoleByContactId.keySet()) {
            if (!creditedContactIds.contains(contactId)) {
                OpportunityContactRole role = new OpportunityContactRole(
                    OpportunityId = opportunityId,
                    ContactId     = contactId,
                    Role          = desiredRoleByContactId.get(contactId),
                    IsPrimary     = (contactId == donorId)
                );
                toInsert.add(role);
            }
        }

        // Delete first so a contact can never temporarily hold two roles.
        if (!toDelete.isEmpty()) {
            delete toDelete;
        }
        if (!toUpdate.isEmpty()) {
            update toUpdate;
        }
        if (!toInsert.isEmpty()) {
            insert toInsert;
        }
    }

    /**
     * Ensures the Opportunity has exactly one payment: paid, for the full
     * amount, dated on the gift date. Any payment NPSP created on Opportunity
     * insert is reused/updated instead of being duplicated.
     */
    private static void applyPayment(Id opportunityId, Decimal amount, Date giftDate) {
        List<npe01__OppPayment__c> existingPayments = [
            SELECT Id
            FROM npe01__OppPayment__c
            WHERE npe01__Opportunity__c = :opportunityId
            ORDER BY CreatedDate ASC, Id ASC
        ];

        if (existingPayments.isEmpty()) {
            insert new npe01__OppPayment__c(
                npe01__Opportunity__c    = opportunityId,
                npe01__Payment_Amount__c = amount,
                npe01__Payment_Date__c   = giftDate,
                npe01__Scheduled_Date__c = giftDate,
                npe01__Paid__c           = true
            );
            return;
        }

        npe01__OppPayment__c payment = existingPayments[0];
        payment.npe01__Payment_Amount__c = amount;
        payment.npe01__Payment_Date__c   = giftDate;
        payment.npe01__Scheduled_Date__c = giftDate;
        payment.npe01__Paid__c           = true;
        update payment;

        List<npe01__OppPayment__c> duplicates = new List<npe01__OppPayment__c>();
        for (Integer i = 1; i < existingPayments.size(); i++) {
            duplicates.add(existingPayments[i]);
        }
        if (!duplicates.isEmpty()) {
            delete duplicates;
        }
    }
}
